//! OVSDB client via D-Bus (zbus)
//!
//! This module provides an OVSDB client for OVS bridge management.
//! It uses D-Bus (zbus) to call the `org.opdbus.v1.Ovsdb.JsonRpc.transact`
//! interface at `/org/opdbus/v1/plugins/ovsdb` on the system bus.
//!
//! Per AGENTS.md §4: D-Bus is the ONLY control plane.

use anyhow::{anyhow, Result};
use serde_json::json;
use serde_json::Value;
use simd_json::OwnedValue as SimdValue;
use std::time::Duration;
use tokio::time::timeout;
use tracing::{info, warn};

const DBUS_BUS_NAME: &str = "org.opdbus.v1.plugins.ovsdb";
const DBUS_OBJECT_PATH: &str = "/org/opdbus/v1/plugins/ovsdb";
const DBUS_INTERFACE: &str = "org.opdbus.v1.Ovsdb.JsonRpc";

/// OVSDB JSON-RPC client via D-Bus
pub struct OvsdbClient {
    timeout: Duration,
}

impl OvsdbClient {
    /// Create a new OVSDB client using D-Bus
    pub fn new() -> Self {
        Self {
            timeout: Duration::from_secs(30),
        }
    }

    /// Create with a custom timeout
    pub fn with_timeout(mut self, timeout: Duration) -> Self {
        self.timeout = timeout;
        self
    }

    /// Execute a transaction via D-Bus
    async fn transact_dbus(&self, operations: Value) -> Result<Value> {
        let conn = zbus::Connection::system().await
            .map_err(|e| anyhow!("Failed to connect to system D-Bus: {}", e))?;

        let proxy: zbus::Proxy<'_> = zbus::proxy::Builder::new(&conn)
            .destination(DBUS_BUS_NAME)?
            .path(DBUS_OBJECT_PATH)?
            .interface(DBUS_INTERFACE)?
            .build()
            .await
            .map_err(|e| anyhow!("Failed to build D-Bus proxy: {}", e))?;

        let result: String = proxy
            .call("Transact", &(&operations.to_string(),))
            .await
            .map_err(|e| anyhow!("D-Bus transact call failed: {}", e))?;

        let result: Value = serde_json::from_str(&result)
            .map_err(|e| anyhow!("Failed to parse transact result: {}", e))?;
        Ok(result)
    }

    /// Execute a transaction with timeout
    async fn transact_with_timeout(&self, db: &str, operations: Value) -> Result<Value> {
        let params = json!([db, operations]);
        let result = timeout(self.timeout, self.transact_dbus(params))
            .await
            .map_err(|_| anyhow!("Transaction timed out"))??;
        Ok(result)
    }

