    async fn transact_with_timeout(&self, _db: &str, operations: Value) -> Result<Value> {
        let result = timeout(self.timeout, self.transact_dbus(operations))
            .await
            .map_err(|_| anyhow!("Transaction timed out"))??;
        Ok(result)
    }

